tool_calls:
cd /home/eval/recon; mkdir -p out; cat > recon.sh <<'EOF'
#!/bin/bash
# Reconcile ledger.csv vs bank.tsv -> out/reconciliation.txt
cd "$(dirname "$0")"
awk '
function tocents(s,   neg,ip,fp,n){
  gsub(/[\r ,]/,"",s); neg=0
  if (s ~ /^-/){neg=1; s=substr(s,2)} else if (s ~ /^\+/) s=substr(s,2)
  n=index(s,"."); if(n){ip=substr(s,1,n-1); fp=substr(s,n+1)} else {ip=s; fp=""}
  if(ip=="") ip="0"
  fp=fp "000"
  c=ip*100 + substr(fp,1,2) + (substr(fp,3,1)>=5 ? 1 : 0)
  return neg ? -c : c
}
function fmt(c,  sg){ sg=""; if(c<0){sg="-"; c=-c}; return sprintf("%s%d.%02d", sg, int(c/100), c%100) }
function trim(s){ gsub(/^[ \t\r]+|[ \t\r]+$/,"",s); return s }
# RFC4180 line parser (fields with embedded newlines not expected)
function parsecsv(line, f,   n,i,c,q,cur){
  n=0; cur=""; q=0
  for(i=1;i<=length(line);i++){
    c=substr(line,i,1)
    if(q){ if(c=="\""){ if(substr(line,i+1,1)=="\""){cur=cur "\"";i++} else q=0 } else cur=cur c }
    else if(c=="\"") q=1
    else if(c==","){ f[++n]=cur; cur="" }
    else cur=cur c
  }
  f[++n]=cur; return n
}
FNR==NR {
  sub(/\r$/,""); if(FNR==1||$0=="") next
  parsecsv($0,f); id=trim(f[1])
  lrows++; L[id]=1; ld[id]=trim(f[2]); la[id]=tocents(f[4]); ltot+=la[id]; next
}
{
  sub(/\r$/,""); if(FNR==1||$0=="") next
  split($0,f,"\t"); id=toupper(trim(f[1]))
  split(trim(f[2]),d,"/"); dt=sprintf("%04d-%02d-%02d",d[3],d[2],d[1])
  a=tocents(f[4]); key=id SUBSEP dt SUBSEP a
  if(key in seen){dups++; next}
  seen[key]=1; brows++; B[id]=1; bd[id]=dt; ba[id]=a; btot+=a
}
END{
  printf "ledger_rows: %d\nbank_rows: %d\nduplicate_bank_rows: %d\n", lrows, brows, dups+0
  printf "ledger_total: %s\nbank_total: %s\n", fmt(ltot), fmt(btot)
  m=0
  for(id in L) if(id in B){
    if(la[id]==ba[id] && ld[id]==bd[id]) m++
    if(la[id]!=ba[id]) am[id]="  " id " ledger=" fmt(la[id]) " bank=" fmt(ba[id])
    if(ld[id]!=bd[id]) dm[id]="  " id " ledger=" ld[id] " bank=" bd[id]
  } else mb[id]="  " id
  for(id in B) if(!(id in L)) ml[id]="  " id
  print "matched: " m
  section("amount_mismatch", am); section("date_mismatch", dm)
  section("missing_in_bank", mb); section("missing_in_ledger", ml)
}
function section(name, arr,   n,k,i,j,t,keys){
  n=0; for(k in arr) keys[++n]=k
  for(i=2;i<=n;i++){t=keys[i]; for(j=i-1;j>=1 && keys[j]>t;j--) keys[j+1]=keys[j]; keys[j+1]=t}
  print name ": " n
  for(i=1;i<=n;i++) print arr[keys[i]]
}
' ledger.csv bank.tsv > out/reconciliation.txt
EOF
chmod +x recon.sh; ./recon.sh; cat out/reconciliation.txt

